ATTACH DATABASE '' AS aux; PRAGMA aux.cache_size=-100; CREATE TABLE aux.t1(a INTEGER PRIMARY KEY, b); WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<100) INSERT INTO aux.t1 SELECT x, substr(replace(hex(zeroblob(450)), '00', CAST(x AS TEXT) || '.'), 1, 900) FROM c; INSERT INTO main.result SELECT count(*), min(a), max(a), sum(b=substr(replace(hex(zeroblob(450)), '00', CAST(a AS TEXT) || '.'), 1, 900)) FROM aux.t1; DETACH DATABASE aux;